156	    public ValueSerializer<?> createContextual(SerializationContext ctxt,
157	            BeanProperty property)
158	    {
159	        TypeSerializer vts = _valueTypeSerializer;
160	        if (vts != null) {
161	            vts = vts.forProperty(ctxt, property);
