169	            if (_staticTyping || ctxt.isEnabled(MapperFeature.USE_STATIC_TYPING)
170	                    || _valueType.isFinal()) {
171	                // false -> no need to cache
172	                /* 10-Mar-2010, tatu: Ideally we would actually separate out type
173	                 *   serializer from value serializer; but, alas, there's no access
