175	                 */
176	                // I _think_ this can be considered a primary property...
177	                ser = ctxt.findPrimaryPropertySerializer(_valueType, property);
178	                ser = _withIgnoreProperties(ser, _ignoredProperties);
179	                /* 09-Dec-2010, tatu: Turns out we must add special handling for
180	                 *   cases where "native" (aka "natural") type is being serialized,
181	                 *   using standard serializer
182	                 */
183	                boolean forceTypeInformation = isNaturalTypeWithStdHandling(_valueType.getRawClass(), ser);
184	                return withResolved(property, vts, ser, forceTypeInformation);
185	            }
186	            // [databind#2822]: better hold on to "property", regardless
187	            if (property != _property) {
188	                return withResolved(property, vts, ser, _forceTypeInformation);
189	            }
190	        } else {
191	            // 05-Sep-2013, tatu: I _think_ this can be considered a primary property...
192	            ser = ctxt.handlePrimaryContextualization(ser, property);
193	            return withResolved(property, vts, ser, _forceTypeInformation);
194	        }
195	        return this;
196	    }
