205	    public void serialize(final Object bean, final JsonGenerator gen,
206	            final SerializationContext ctxt)
207	        throws JacksonException
208	    {
209	        Object value;
210	        try {
211	            value = _accessor.getValue(bean);
212	        } catch (Exception e) {
213	            wrapAndThrow(ctxt, e, bean, _accessor.getName() + "()");
214	            return; // never gets here
215	        }
216	        if (value == null) {
217	            ctxt.defaultSerializeNullValue(gen);
218	            return;
219	        }
220	        ValueSerializer<Object> ser = _valueSerializer;
221	        if (ser == null) {
222	            ser = _findSerializer(ctxt, value);
223	        }
224	        if (_valueTypeSerializer != null) {
225	            ser.serializeWithType(value, gen, ctxt, _valueTypeSerializer);
226	        } else {
227	            ser.serialize(value, gen, ctxt);
228	        }
229	    }
